import { useParams } from "react-router-dom";
import { useState, useEffect } from "react";
import { getProduitParId } from "../services/serviceProduits";
import { getAvis, ajouterAvis } from "../services/serviceAvis";
import NotesEtoiles from "../components/commun/NotesEtoiles";
import CarteAvis from "../components/commun/CarteAvis";
import { usePanier } from "../hooks/usePanier";

export default function DetailProduit() {
  const { id } = useParams();
  const [produit, setProduit] = useState(null);
  const [avis, setAvis] = useState([]);
  const [nouvelAvis, setNouvelAvis] = useState({ auteur: "", note: 5, commentaire: "" });
  const { ajouterAuPanier } = usePanier();

  useEffect(() => {
    getProduitParId(id).then(setProduit);
    setAvis(getAvis(id));
  }, [id]);

  const soumettreAvis = () => {
    ajouterAvis(id, nouvelAvis);
    setAvis(getAvis(id));
    setNouvelAvis({ auteur: "", note: 5, commentaire: "" });
  };

  if (!produit) return <p style={{ padding: "40px", textAlign: "center" }}>Chargement...</p>;

  return (
    <div style={{ padding: "30px", maxWidth: "900px", margin: "0 auto" }}>
      <div style={{ display: "flex", gap: "30px", flexWrap: "wrap" }}>
        <img src={produit.image} alt={produit.title} style={{ width: "280px", objectFit: "contain" }} />
        <div style={{ flex: 1 }}>
          <h2>{produit.title}</h2>
          <NotesEtoiles note={produit.rating?.rate} />
          <p style={{ fontSize: "28px", color: "#e44d26", margin: "16px 0" }}>{produit.price} €</p>
          <p style={{ color: "#555", marginBottom: "20px" }}>{produit.description}</p>
          <button onClick={() => ajouterAuPanier(produit)} style={{ backgroundColor: "#e44d26", color: "white", border: "none", padding: "12px 24px", borderRadius: "6px", cursor: "pointer", fontSize: "16px" }}>
            Ajouter au panier 🛒
          </button>
        </div>
      </div>

      <div style={{ marginTop: "40px" }}>
        <h3>Avis clients</h3>
        {avis.map((a, i) => <CarteAvis key={i} avis={a} />)}

        <div style={{ marginTop: "20px", backgroundColor: "white", padding: "20px", borderRadius: "8px" }}>
          <h4>Laisser un avis</h4>
          <input placeholder="Votre nom" value={nouvelAvis.auteur} onChange={(e) => setNouvelAvis({ ...nouvelAvis, auteur: e.target.value })} style={{ display: "block", width: "100%", padding: "8px", margin: "8px 0", borderRadius: "6px", border: "1px solid #ddd" }} />
          <textarea placeholder="Votre commentaire" value={nouvelAvis.commentaire} onChange={(e) => setNouvelAvis({ ...nouvelAvis, commentaire: e.target.value })} style={{ display: "block", width: "100%", padding: "8px", margin: "8px 0", borderRadius: "6px", border: "1px solid #ddd", minHeight: "80px" }} />
          <button onClick={soumettreAvis} style={{ backgroundColor: "#e44d26", color: "white", border: "none", padding: "10px 20px", borderRadius: "6px", cursor: "pointer" }}>
            Envoyer
          </button>
        </div>
      </div>
    </div>
  );
}
